package com.bookstore.book.controller;
import com.bookstore.book.dto.BookRequest; import com.bookstore.book.entity.Book; import com.bookstore.book.service.BookService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/books") public class BookController { private final BookService service; private final com.bookstore.book.repository.BookRepository repo; public BookController(BookService service,com.bookstore.book.repository.BookRepository repo){this.service=service;this.repo=repo;} @GetMapping public List<Book> all(@RequestParam(required=false) String search){return search==null?service.all():repo.findByTitleContainingIgnoreCase(search);} @GetMapping("/{id}") public Book byId(@PathVariable Long id){return service.byId(id);} @PreAuthorize("hasRole('ADMIN')") @PostMapping public Book create(@Valid @RequestBody BookRequest r){return service.create(r);} @PreAuthorize("hasRole('ADMIN')") @PutMapping("/{id}") public Book update(@PathVariable Long id,@Valid @RequestBody BookRequest r){return service.update(id,r);} @PreAuthorize("hasRole('ADMIN')") @PreAuthorize("hasRole('ADMIN')") @PatchMapping("/{id}/stock") public Book stock(@PathVariable Long id,@RequestParam Integer value){return service.adjustStock(id,value);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.delete(id);} }


